insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 1, 'When the engine will not accept an input, what does the call hand back?', '["A full voyage plan in which the refused input is swapped for a typical figure the engine keeps, with a warning added to the reasons.", "Zeros in every field of the plan, so that a bad input shows up as a voyage that adds up to nothing at all.", "An object carrying an error and a field, where the field names the refused input and the message begins with that name.", "A numbered error code with no message, which the learner looks up in a table printed at the end of the course."]'::jsonb, 2, 'A refusal is an object with an error and a field, and the message starts with the name of the field it refuses and states the condition that failed. The engine keeps no typical figure to swap in, it never returns zeros in place of a refusal, and every message is printed in the engine''s own words, so there is no code to look up.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 2, 'Which five functions does the engine export for the course''s calculator panels to call?', '["voyagePlan, fleetSize, fleetVariability, deckPlan and shoreBase, one function for each question.", "voyagePlan, fleetSize, deckPlan, shoreBase and a scheduler that sets each departure time by the clock.", "Only voyagePlan and fleetSize, since the deck and the base are worked in the Suite app alone.", "A single planner function that takes every input at once and returns the voyage, the fleet, the deck and the base together."]'::jsonb, 0, 'The exported functions are voyagePlan, fleetSize, fleetVariability, deckPlan and shoreBase, beside ACCEPTED_KEYS, ACTIVITIES and DEFAULTS. The engine plans no schedule by the clock, the deck and the base have their own panels in the course, and each question is its own function with its own inputs.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 3, 'The course''s table of sources gives each text the date it was read. What is that date?', '["26 March 2015, the date printed on Adan and Resing''s queueing lecture notes.", "20 June 2001, the draft date of Iversen''s handbook.", "1 February 2024, the issue date of the Skoko et al. paper, which is the main offshore source.", "2026-09-27, the same date for every text in the table, whatever the text''s own edition."]'::jsonb, 3, 'Every text was read on 2026-09-27. The other three dates are real, and each is an edition date of one text: 26 March 2015 for Adan and Resing, 20 June 2001 for Iversen''s draft and 1 February 2024 for Skoko et al. The table gives each edition beside the date it was read.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 4, 'Aas, Halskau and Wallace, Maritime Economics & Logistics 11(3), 302-325 (2009), is under publisher copyright. How does the course use it?', '["It quotes the paper''s sentences with credit in each lesson, because the paper carries the same CC BY 4.0 licence as Skoko et al.", "By concept only: its ideas on deck cargo by area, segregated tanks and weather limits are explained in the course''s own words.", "Cited by table: a worked fleet-sizing example from the paper, with the inputs and the vessel count that the engine checks.", "It pastes the paper''s wording under a share-alike notice, the way the Wikipedia article on first-fit decreasing is reproduced."]'::jsonb, 1, 'A publisher''s text is taught by concept only, and none of its prose appears. It is not CC BY 4.0, and the course found no openly readable paper that prints a fleet-sizing example with its inputs and a vessel count. The Wikipedia article is cited by section and example, and its wording is not pasted either.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 5, 'Skoko et al. (J. Mar. Sci. Eng. 12(2), 263, 1 February 2024) is licensed CC BY 4.0. How does the course cite it?', '["By long quotation with credit, as the licence allows.", "By table, with every explanation still written in the course''s own words.", "By concept only, like a publisher''s text.", "It is left out of the course, since its PSV fuel total could not be reproduced by the engine."]'::jsonb, 1, 'Both CC BY 4.0 texts would allow quotation with credit, and the course still cites them by table and equation so that every explanation is its own. Concept-only use is kept for the publisher''s text. The paper is cited throughout: only its printed PSV month total is set aside, because the rounded days the table prints do not reproduce it, and its AHTS row is used.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 6, 'What does the fixture file of the Ekene cluster state about itself?', '["That it reproduces an operating cluster in the Niger Delta, with the vessel and installation names changed so that no operator can be traced.", "That its distances, field hours and demand were read from the tables of Aas, Halskau and Wallace (2009) and then scaled to one week of supply.", "That its fuel burns and deck areas are the builder''s figures for two named vessels now in service, as printed in their own data sheets.", "That it is synthetic teaching data written by a stated script, and no real company, vessel, port, installation or contract appears in it."]'::jsonb, 3, 'The file labels itself SYNTHETIC teaching data for the Ekene field, a fictional teaching field, given a fictional offshore cluster, and says no real company, vessel, port, installation or contract appears. A stated script wrote it. It was not scaled from any paper, and its figures are its own stated inputs.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 7, 'The Ekene PSV is stated at 11 knots. What does the engine read that speed as, and what does it do with it?', '["11 nautical miles an hour, and each leg''s calm hours are its NM divided by 11.", "11 kilometres an hour, which the engine converts to NM before any leg is divided.", "11 NM covered in a day of sailing, so each leg''s days are its NM over 11 and its hours follow from the days.", "A cruising figure the engine slows as the deck fills."]'::jsonb, 0, 'Speeds are in knots, nautical miles an hour, and sailing hours are the distance over the speed: the first Ekene leg of 62.000000 NM takes 5.636364 calm hours at 11 knots. The engine converts no units and reads no load into the speed; it applies the one stated speed to every leg.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 8, 'Two figures the engine compares, a load and a capacity, differ only in their last binary digit. By the engine''s stated rule, when do they count as equal?', '["When they agree at six decimals, since six decimals is how the panel, the lessons and the course''s tables print every figure the engine returns.", "When they agree at two decimals, the precision to which the published tables print their figures.", "When they agree to 12 significant digits, the TIE_DIGITS the engine exports, so noise in the last binary digit cannot decide a check.", "Only when they are identical as binary doubles, bit for bit, since any looser test could hide a real overload of a constraint."]'::jsonb, 2, 'Two figures tie when they agree to 12 significant digits. A capacity check passes when the twelve-digit figure of the load is at or below that of the capacity, and a count rounded up takes the ceiling of the twelve-digit figure. Six decimals is only how figures are printed: two figures printed alike are not thereby equal. Two decimals is a source''s printing, and a bit-for-bit test would let decimal noise decide the answer.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 9, 'How does the engine print a figure inside a sentence it writes, such as a reason?', '["Every figure to six decimals with its trailing zeros kept, exactly as the numeric field beside it is printed in each of the panel''s tables.", "Money rounded to the nearest whole unit and every quantity to two decimals, the way the published tables print theirs.", "Every figure in full double precision, so that the reason and the numeric field beside it always read the same, digit for digit, on every line.", "Money to the cent and a computed quantity to six decimals, half away from zero with trailing zeros dropped; a stated input as typed."]'::jsonb, 3, 'Inside a message the engine rounds money to the cent and a computed quantity to six decimals, half away from zero, drops trailing zeros and prints a stated input as it was given. So a reason reads 540 m2 of 600 m2 (90%) while the numeric field keeps full precision and the course quotes it as 0.900000.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 10, 'Which figures does the engine hold as its own, with no input stating them?', '["Only its caps and the twelve-digit tie rule in DEFAULTS; every speed, burn, capacity, fraction and price is a stated input.", "A standard PSV speed of 10 knots and burns of 0.5 and 0.03 t an hour, read from Skoko et al. and applied to any vessel.", "A usable deck fraction of 0.75 for every vessel, which a call may override when it states a fraction of its own.", "The rainy-season weather factor of 1.2 on sailing and field time, applied whenever a call leaves the weather out."]'::jsonb, 0, 'The only figures the engine holds are its caps and the tie rule in DEFAULTS. The 10 knots and the burns of 0.5 and 0.03 are Skoko et al.''s printed figures and enter only as stated inputs; 0.75 is the Ekene fixture''s stated fraction; 1.2 is the Ekene planner''s stated allowance. A call that leaves any of them out is refused by name.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 11, 'In the voyage plan view a box states the key fuelPrice where fuelPricePerT belongs, and also leaves the vessel''s speed unstated. What does the engine return?', '["A refusal naming vessel.speedKnots, because a required input that is missing is checked before any unknown key.", "Two refusals together, one for each fault, listed in the order the faults appear in the box.", "A refusal naming fuelPrice as a key it does not accept, because every function checks its accepted keys before it reads an input.", "A plan with a fuel cost of zero, since the misspelt price is ignored, and the hours left blank."]'::jsonb, 2, 'The unknown key is refused first. The engine''s own words are: fuelPrice is not an accepted key; the accepted keys at the top level are vessel, products, installations, route, portHours, weather, fuelPricePerT. A call returns one refusal at a time, and the engine drops no key silently, so a misspelt price is refused where it would otherwise have seemed to apply.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 12, 'Which of these does the engine answer with a refusal?', '["A milk run whose deck cargo is larger than the vessel''s usable deck area, so deck area is overloaded.", "A voyage plan box that leaves the vessel''s speed unstated, an input the engine needs to time the voyage.", "A voyage whose deadweight load, bulk included, comes out above the vessel''s stated cargo deadweight.", "A plan whose binding constraint sits exactly at a utilisation of 1.000000, the capacity itself."]'::jsonb, 1, 'A missing speed is refused: vessel.speedKnots must be a finite number above 0; got nothing, in the engine''s own words. An overloaded deck area or deadweight is a result with its reasons, planned and marked not feasible, and a load exactly at capacity is feasible. The course keeps the word refused for an input the engine would not accept.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 13, 'What is every graded number in this course?', '["A value the engine returns on fixed inputs written down in advance, so each graded question has exactly one right answer.", "A Monte Carlo estimate on a stated seed and draw count, graded within a band wide enough to cover the spread between machines.", "A figure read from a published table and rounded to two decimals, so it matches what the source prints.", "A planner''s judgement on a written case, marked by a tutor against the course''s checklist for checking a voyage plan before it sails."]'::jsonb, 0, 'Every graded number is a return value of the engine on fixed inputs, so the same inputs give the same number on any machine. No graded figure is a Monte Carlo draw, none is a source''s printed figure, and none is a judgement: each is quoted to six decimals as the panel prints it.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 14, 'Which statement about the Marine Logistics Planner, the Suite app for this course, is true?', '["A learner has to open it to finish each exercise, because the course panels only display the figures it sends them.", "It runs its own copy of the engine, tuned separately, so its figures can differ from the course''s in the sixth decimal.", "It is where the capstone is graded, since the course''s calculator panels cannot read a capstone case file at all.", "It runs the same engine file as the course, and every practical also runs in the course''s own panels."]'::jsonb, 3, 'The planner, in the Suite''s Midstream & Downstream module, runs the same engine file on the same Ekene fixture. The course''s four calculator panels call the vendored engine on the learner''s own inputs, so a learner without a Suite seat can work every exercise, and the Associate capstone is worked in the voyage and fleet calculator.'),
  ('marine', 'beginner', 'module', 'm01-offshore-supply-as-a-system', 15, 'The course gives the word voyage a narrow meaning of its own. Which meaning?', '["Any leg between two points of the route, so a milk run with four stops is made of five voyages.", "Each call at an installation, so a milk run through four installations counts as four voyages.", "One sailing from the base and back: a milk run through all of its stops counts as one voyage.", "All the sailing one vessel does in a week, however many times it returns to the base in that week."]'::jsonb, 2, 'The course legislates the word: a voyage is one sailing from the base and back. A leg is one stated distance inside a voyage, a call at an installation is a stop on it, and a week''s sailing is several voyages, which the Professional tier counts.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 1, 'A milk run is stated through four installations. How many leg distances must it state?', '["Four, one for each installation, each measured from the base as a dedicated route measures it.", "Five: base to the first stop, three from stop to stop, and the last stop back to the base.", "Eight, an outward leg and a return leg for every installation the vessel calls at.", "Three, the stop-to-stop legs alone, since the engine works out the two base legs itself."]'::jsonb, 1, 'A milk run states one leg more than it has stops, in the order sailed: base to the first stop, stop to stop, and the last stop back to the base. Distances measured from the base belong to a dedicated route, a milk run does not sail out and back to each stop, and the engine works out no distance it is not given.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 2, 'On a dedicated route, where does the engine take each voyage''s distance from?', '["From the route''s legsNm, read in the order the installations are listed in the box.", "From the longest leg of the milk run, which the engine applies to every installation.", "From a distance the engine measures between the base and each installation''s stated position.", "From each installation''s stated distanceFromBaseNm, sailed out and back."]'::jsonb, 3, 'A dedicated voyage sails from the base to one installation and back at that installation''s stated distance, so the Ekene EKJ voyage sails 136.000000 NM for a distance of 68.000000 NM. Legs are read only on a milk run, and a legsNm stated on a dedicated route is refused. The engine borrows no leg and computes no distance from positions.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 3, 'The Ekene milk run states legs of 62, 9, 12, 28 and 95 NM. What distance does the engine return for the voyage?', '["206.000000 NM, the five legs added in the order sailed.", "124.000000 NM, a dedicated voyage to EKA and back.", "190.000000 NM, twice the 95 NM from EKF.", "148.000000 NM, the distance of the dedicated voyage to EKB, the middle of the cluster."]'::jsonb, 0, 'A milk run''s NM is the sum of its legs: 62 + 9 + 12 + 28 + 95 is 206.000000 NM. The other three figures are the NM of the dedicated voyages to EKA, EKF and EKB, each out and back at its own distance from the base, and none of them is the milk run.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 4, 'The Ekene PSV sails the milk run''s 206.000000 NM at 11 knots with a weather factor of 1 on every activity. What sailing hours does the engine return?', '["22.472727, the sailing hours once the rainy-season factor of 1.2 is applied to them.", "23.000000, the field hours of the four stops.", "18.727273, the NM over the speed with no allowance on it.", "53.727273, the voyage''s total hours, which include port and field time too."]'::jsonb, 2, 'Sailing hours are the NM over the speed: 206 over 11 is 18.727273 hours in calm weather. The factor of 1.2 on sailing lifts them to 22.472727, but this call states a factor of 1. 23.000000 is the field hours and 53.727273 the whole calm voyage.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 5, 'With a weather factor of 1, the Ekene installations EKA, EKJ, EKB and EKF state 6, 8, 4 and 5 field hours. What field hours does the engine return for one milk run through all four?', '["23.000000, the stated field hours of the four installations added up.", "27.600000, the four installations'' field hours after a factor of 1.2 is applied to them.", "8.000000, the jack-up''s field hours alone.", "6.000000, the first stop''s field hours, since a milk run works cargo at only one stop."]'::jsonb, 0, 'Field hours are the sum of the stated field hours of the installations the voyage serves, so the milk run carries 6 + 8 + 4 + 5 = 23.000000 hours in calm weather. 27.600000 is the rainy-season figure with the factor on field time, and a milk run works cargo at every stop, so neither the longest call nor the first one is the answer.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 6, 'How often does the engine count a voyage plan''s stated port hours?', '["Once at every installation the voyage calls at, so a milk run through four stops pays them four times.", "Once a voyage, at the base: a milk run pays them once and four dedicated voyages pay them four times.", "Once a week, spread evenly across all the voyages the vessel sails in that week.", "Only on the return leg of a voyage, and only when the weather factor names port time."]'::jsonb, 1, 'Port hours are the stated hours at the base, counted once a voyage: the Ekene milk run carries 12.000000 port hours, and so does each of the four dedicated voyages. Time alongside an installation is field time, stated per installation. The engine has no week at this tier, and the weather choice changes how long port time is and leaves the count alone.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 7, 'On the Ekene PSV''s dedicated route (11 knots, 12 port hours, a factor of 1.2 on sailing and field time), EKJ is 68.000000 NM from the base with 8 field hours. What total hours does the engine return for the EKJ voyage?', '["32.727273, the total hours of the dedicated voyage to EKA, the nearest installation to the base.", "38.727273, the total hours of the dedicated voyage to EKF, the farthest installation on the route.", "14.836364, the EKJ sailing hours alone.", "36.436364, its sailing, port and field hours added after the factor."]'::jsonb, 3, 'The EKJ voyage sails 136.000000 NM for 14.836364 hours after the factor, spends 12.000000 port hours at the base and 9.600000 field hours alongside the jack-up, for 36.436364 hours in all. 32.727273 and 38.727273 are the EKA and EKF voyages, and 14.836364 leaves out port and field time.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 8, 'What goes into the days the engine returns for a voyage?', '["Sailing hours alone divided by 24, since port and field time are reported as separate standby days.", "The total hours divided by 24 and rounded up to whole days, so every voyage fits a daily schedule.", "Every hour the voyage spends, sailing, port and field, after the weather factor, divided by 24 with no rounding.", "The total hours divided by 12, since a working day alongside an installation is taken as 12 hours."]'::jsonb, 2, 'A voyage''s days are its total hours over 24, after the weather factor: the milk run''s 62.072727 hours are 2.586364 days. The engine counts every activity, rounds nothing into whole days and uses no working day for a voyage. A day here is a planning measure of 24 hours, with no clock behind it.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 9, 'The four Ekene dedicated voyages take 1.363636, 1.518182, 1.372727 and 1.613636 days. What total does the engine return, and how does it compare with the milk run?', '["1.613636 days, the longest of the four, since the four voyages are taken to sail at the same time.", "5.868182 days in all, against 2.586364 days for one milk run voyage through the same four installations.", "2.586364 days, the same as the milk run, since both routes serve exactly the same four installations.", "5.868182 days for the milk run and 2.586364 for the dedicated route, as the milk run sails further."]'::jsonb, 1, 'When a route has several voyages the engine adds the voyages'' days, so the dedicated total is 5.868182 days, and the milk run is a single voyage of 2.586364 days. One vessel sails the dedicated voyages one after another, so the longest alone is not the total, and the milk run is the shorter of the two routes here.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 10, 'Why does one Ekene milk run take fewer days than the four dedicated voyages together, with the same vessel, speed, field hours and weather?', '["It sails fewer NM in all, because the installations sit close together, and it pays the 12 port hours once.", "It sails at a higher speed, since the engine states every milk run at the AHTS''s 12 knots.", "It carries a lower weather factor, since the factor is named only on the dedicated voyages.", "It leaves out the field hours at the installations the vessel passes, since it only stops at one."]'::jsonb, 0, 'The milk run sails 206.000000 NM, where the four dedicated voyages sail 124, 136, 148 and 190 NM, and it pays the port time once where the dedicated route pays it four times. The comparison holds the vessel, the speed, the field hours and the weather the same on both sides, so none of those can explain the gap, and a milk run stops at every installation.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 11, 'Two installations sit at one location. A milk run through them states legs of 30, 0 and 30 NM at 10 knots. What does the engine do with the leg of 0?', '["It refuses the leg, since every leg distance must be a finite number above 0 NM.", "It merges the two stops and asks for two legs.", "It replaces the 0 with the smallest positive leg of the route so no leg takes no time.", "It accepts it, and returns 6.000000 sailing hours for the voyage."]'::jsonb, 3, 'A leg may be 0 NM: the rule is a finite number at or above 0, so the leg is accepted and the voyage sails 60 NM at 10 knots, 6.000000 hours. Only a negative leg is refused. The engine merges no stops and replaces no stated figure.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 12, 'The Ekene milk run''s stops are stated as EKA, EKJ, EKB, with EKF left out. What does the engine return?', '["A voyage plan through the three stops named, with EKF left off the route and its cargo left at the base.", "A refusal, in its own words: route.stops[3] must be an installation id (EKA, EKJ, EKB, EKF); got \"EKX\"", "A refusal, in its own words: route.stops must be an array naming each of the 4 installations once, in the order sailed; got [\"EKA\",\"EKJ\",\"EKB\"]", "A refusal, in its own words: route.legsNm must be an array of 5 leg distances in nautical miles (base to the first stop, stop to stop, the last stop back to the base); got [62,9,12,28]"]'::jsonb, 2, 'A milk run must name every installation of the call once, so a missing stop is refused on route.stops and the message prints the three stops it got. The engine plans no partial route. The message about route.stops[3] answers an unknown id, EKX, and the legsNm message answers four legs stated for four stops.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 13, 'A milk run''s stops are typed as EKA, EKJ, EKA, EKF. Which field does the engine''s refusal name?', '["route.stops[2], the third entry, where EKA is named for the second time.", "route.stops[0], the first entry, where EKA is named for the first time on the route.", "route.legsNm, since a repeated stop leaves one leg of the route with no destination.", "installations[0].id, the first installation listed."]'::jsonb, 0, 'The engine''s own words are: route.stops[2] repeats "EKA"; a milk run visits each installation once. The first naming of EKA is valid, and the repeat is where the fault sits. The legs and the installation list are not at fault, and the message starts with the field it refuses, so the panel points at the third stop.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 14, 'A milk run box also states distanceFromBaseNm of 62 for EKA, the first installation in the call. What does the engine return?', '["The 62 NM is sailed out to EKA first and the stated legs from there, the distance added as an extra leg at the start of the milk run, with the rest unchanged.", "A refusal, in its own words: installations[0].distanceFromBaseNm is read only when route.mode is \"dedicated\"; a milk run takes its distances from route.legsNm", "A voyage plan that sails the stated legs and quietly drops the distance from the base, since a milk run has no use for it, with no word about it in the reasons.", "A refusal, in its own words: installations[0].distanceFromBaseNm must equal route.legsNm[0] on a milk run; got 62"]'::jsonb, 1, 'Each route mode reads its own distances, and a distance given to the mode that does not read it is refused by name. The engine compares no distance with a leg, drops no input silently and adds no leg of its own: the route mode is a required input the call states.'),
  ('marine', 'beginner', 'module', 'm02-routes-and-voyage-time', 15, 'A milk run through four stops states only four legs, 62, 9, 12 and 28 NM. Which input is refused, and why?', '["route.stops, since four legs can serve only three stops, so the engine asks for a stop to be removed.", "Nothing: the engine closes the route by sailing the first leg in reverse, 62 NM back to the base.", "vessel.speedKnots, since the voyage''s sailing hours cannot be found until every leg is stated.", "route.legsNm, since four stops need 5 legs, and the last one, back to the base, is missing."]'::jsonb, 3, 'The engine''s own words are: route.legsNm must be an array of 5 leg distances in nautical miles (base to the first stop, stop to stop, the last stop back to the base); got [62,9,12,28]. The stops are valid, the engine invents no return leg, and the speed is stated, which clears it.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 1, 'What weather factors does the engine accept in a voyage plan?', '["Any number above 0, so a factor of 0.9 can model a following sea that shortens a voyage.", "Only 1 or 1.2, the two Ekene factors.", "A factor from the engine''s own table of seasons, looked up by the month the voyage sails in.", "Any finite number from 1 to 10, both ends accepted, with 1 the calm voyage."]'::jsonb, 3, 'The weather factor is a stated number from 1 to 10. A factor of 1 is calm, and 10 is the cap in DEFAULTS; 0.9 and 10.5 are both refused. The Ekene figures are the fixture''s stated inputs, one choice among many, and the engine keeps no table of seasons.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 2, 'To model a following sea, a planner types 0.9 into the weather factor control. What is the outcome?', '["A plan in which every activity the factor names runs a tenth faster than its calm time.", "A refusal, in its own words: weather.factor must be a finite number from 1 to 10; got 0.9", "A plan with the factor raised to 1, the calm floor, and a note of the change in the reasons.", "A refusal, in its own words: weather.factor must be a finite number above 1; got 0.9"]'::jsonb, 1, 'A factor below 1 would make bad weather faster than calm, so the engine refuses it on weather.factor, printing the value it got. It changes no stated input to fit, and the activities are a separate input with their own refusals. A factor of exactly 1, the calm plan, is accepted, so the range starts at 1.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 3, 'Port time on the Ekene milk run is stated as 12 hours. If the planner puts port in the list the 1.2 allowance slows, how long is port time in the plan?', '["14.400000, the 12 stated hours times the factor, since port time is named.", "12.000000, the stated hours, since the weather factor never reaches the time at the base.", "27.600000, the weathered field hours.", "22.472727, the weathered sailing hours."]'::jsonb, 0, 'An activity named in weather.appliesTo is multiplied by the factor, so port time becomes 14.400000 hours. 12.000000 is the port time when port is left out of the list, as in the Ekene rainy-season plan. 27.600000 and 22.472727 are the field and sailing hours.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 4, 'With 1.2 on sailing and field time the Ekene milk run takes 62.072727 hours. The same plan with port time named as well returns what total hours?', '["62.072727, since port time at the base is never slowed by the weather in the engine.", "53.727273, since a factor on every activity is read by the engine as the calm case.", "64.472727, since port time grows from 12.000000 to 14.400000 hours.", "2.686364, the total with all three slowed."]'::jsonb, 2, 'Naming port time lifts the port hours from 12.000000 to 14.400000, and the voyage to 64.472727 hours in all. The engine slows any activity the list names, including port time. 53.727273 is the calm voyage at a factor of 1, and 2.686364 is the same voyage''s figure in days.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 5, 'In a voyage plan box, weather.appliesTo is missing while the factor is stated as 1.2. What comes back?', '["A plan with the factor applied to all three activities, the list the engine assumes when none is given.", "A plan with the factor applied to sailing alone, the activity the weather slows the most at sea, with port and field time kept at their calm hours.", "A refusal, in its own words: weather.appliesTo must be an array naming at least one of \"sailing\", \"port\", \"field\"; got nothing", "A refusal, in its own words: weather.factor must be 1 when weather.appliesTo is left out; got 1.2"]'::jsonb, 2, 'The list of activities is a required input with no assumed value, so leaving it out is refused by name, on weather.appliesTo itself whatever the factor. The engine applies the factor to no activity of its own choosing and sets no stated input aside: the plan names both the factor and what it slows.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 6, 'A planner wants standby time slowed by the weather and adds standby to weather.appliesTo after sailing. What does the engine return, and what can the planner do?', '["A refusal: the activities are sailing, port and field only, so standby is folded into the stated port or field hours.", "A plan with a fourth activity added for standby, burning fuel at a rate read from Skoko et al.''s tables.", "A plan that treats standby as port time and applies the factor to it without a word in the reasons.", "A refusal asking for standby to be stated in days, since standby is counted by the day offshore."]'::jsonb, 0, 'The engine''s own words are: weather.appliesTo[1] must be one of "sailing", "port", "field"; got "standby". ACTIVITIES holds three names only, so standby has no activity and no burn of its own. The engine renames nothing silently, and it asks for no days. The planner folds standby into the stated port or field hours and says so.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 7, 'Between the calm Ekene milk run (factor 1) and the rainy-season run (1.2 on sailing and field time), which figure stays the same?', '["The total hours, 53.727273 in both, since the factor applies to the fuel burn and leaves the hours alone, so only the bill moves.", "The fuel cost, 14462.563636 in both, since the fuel is priced per voyage and each season sails one voyage.", "The days, 2.238636 in both, since a voyage''s days count the sailing hours and exclude the field time the factor slows.", "The deck area utilisation, 0.900000 in both, since the weather changes time and fuel and leaves the cargo where it is."]'::jsonb, 3, 'Weather multiplies time, and fuel follows time, so the hours rise from 53.727273 to 62.072727, the days from 2.238636 to 2.586364 and the fuel cost from 14462.563636 to 17292.436364. The cargo, the capacities and so every utilisation stay the same, with deck area at 0.900000.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 8, 'How does the engine find the fuel of a voyage?', '["The NM sailed times a stated tonnes per NM, with the fuel in port and at the field left out of the voyage''s total.", "The hours in each activity times the stated tonnes an hour for that activity, added over sailing, port and field.", "A speed-cube law on the stated speed, which the weather factor then scales on top of the hours it adds.", "The total hours times one average burn for the whole voyage, taken from the Skoko et al. tables."]'::jsonb, 1, 'Fuel is hours by activity times the stated burn for that activity. There is no speed-cube law and no per-NM burn, and the weather factor raises fuel only through the hours it adds. Each activity has its own stated burn, so one average rate would lose the difference between 0.5 t an hour sailing and 0.03 t an hour in port.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 9, 'Sailing hours of 22.472727 at a stated sailing burn of 0.5 t an hour give how much sailing fuel?', '["11.236364 t, the sailing hours times the sailing burn.", "9.363636 t, the calm sailing fuel.", "8.280000 t, the field fuel, from 27.600000 field hours at the field burn of 0.3 t an hour.", "19.876364 t, the voyage''s total fuel."]'::jsonb, 0, '22.472727 hours at 0.5 t an hour is 11.236364 t. The calm voyage sails 18.727273 hours and burns 9.363636 t; 8.280000 t is the field fuel and 19.876364 t the voyage''s total.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 10, 'Naming port time in the allowance lifts the Ekene milk run''s port hours from 12.000000 to 14.400000. At a port burn of 0.03 t an hour, what does the voyage''s total fuel do?', '["It stays at 19.876364 t, because the engine sets a voyage''s fuel from its sailing hours alone.", "It rises to 23.880000 t, all three slowed.", "It rises by 2829.872727 t, the whole rainy-season allowance, since port time is now weathered too.", "It rises from 19.876364 to 19.948364 t, because port burns so little an hour."]'::jsonb, 3, 'The extra port hours burn at only 0.03 t an hour, so the port fuel moves from 0.360000 to 0.432000 t and the total from 19.876364 t to 19.948364 t. Fuel follows the hours in every activity. 23.880000 t is the AHTS''s fuel on the same route, and 2829.872727 is money, the fuel cost the allowance on sailing and field time adds to the calm voyage.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 11, 'The rainy-season Ekene milk run burns 19.876364 t, and the fuel price is stated at 870 a tonne. What fuel cost does the engine return?', '["14462.563636, the calm voyage''s cost.", "17292.436364, the tonnes times the stated price.", "17355.076364, the fuel cost with the factor named on port time as well as sailing and field.", "20775.600000, the fuel cost of the AHTS Ekene Tide on the same route and at the same price."]'::jsonb, 1, 'The fuel cost is the tonnes times the stated price: 19.876364 t at 870 is 17292.436364. The other three are the engine''s figures for other plans: the calm voyage, the plan with port time weathered, and the AHTS voyage.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 12, 'At a stated 870 a tonne, by how much does the rainy-season allowance on sailing and field time raise the Ekene milk run''s fuel bill over the calm voyage?', '["62.640000, the extra cost of naming port time in the allowance as well as sailing and field.", "17292.436364, the whole of the rainy-season fuel bill, which the allowance is taken to cause.", "2829.872727, the rainy-season cost 17292.436364 less the calm cost 14462.563636.", "14462.563636, the calm fuel bill, which the rainy-season allowance is taken to double."]'::jsonb, 2, 'The allowance adds 2829.872727 to the bill, the difference of the two engine fuel costs. 62.640000 is what naming port time adds on top of that. The calm voyage still burns fuel, so the whole rainy-season bill is not the allowance, and a factor of 1.2 on two activities does not double anything.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 13, 'The PSV day of Skoko et al. (Tables 1 and 4) is put through the engine as one out-and-back trip of 120 NM each way at 10 knots, with 24 hours alongside the base, no field hours and a weather factor of 1, burning 0.5 t an hour under way and 0.03 in port, fuel priced at 870. What comes back?', '["A fuel cost of 11066.400000, whose sailing part 10440.000000 and port part 626.400000 are the two daily figures the table prints.", "A fuel cost of 10440.000000 in all, since the table counts the sailing day only and a day in port burns nothing.", "A fuel cost of 626.400000 in all, since a PSV at the economic speed spends the whole of the day in port.", "A fuel cost of 11066.400000, which misses the table''s printed daily figures by the cost of a day in port."]'::jsonb, 0, 'The voyage sails 240.000000 NM in 24.000000 hours and burns 12.000000 t sailing and 0.720000 t in port, for 11066.400000 at 870. The two parts, 10440.000000 and 626.400000, are exactly the daily sailing and port costs the paper prints. A port day burns 0.03 t an hour, a small amount that is still counted.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 14, 'For the AHTS optimal month in Skoko et al.''s Tables 5 and 7, the course states 168 field hours, navigation as a dedicated voyage of 79.2 NM each way at 11 knots, 57.6 port hours, burns of 0.5 t an hour sailing and in the field and 0.03 in port, a weather factor of 1, and 870 a tonne. Which fuel cost results?', '["186214.104000, the figure the table''s rounded days give for the month through the engine.", "11066.400000, the fuel cost of one day of a PSV at sea and one in port, at the same price.", "92.928000, the fuel cost of the month with the price of 870 left out of the product.", "80847.360000, from 92.928000 t, the optimal fuel cost the paper prints."]'::jsonb, 3, 'The engine returns 14.400000 sailing hours, 92.928000 t and a fuel cost of 80847.360000, the printed AHTS figure exactly. 186214.104000 is what the rounded PSV days give, 11066.400000 is the PSV daily check, and 92.928000 is the tonnes, which the engine multiplies by the stated price.'),
  ('marine', 'beginner', 'module', 'm03-weather-and-fuel', 15, 'Why does the course leave out Skoko et al.''s printed PSV month total of USD 186,274.10 and use the AHTS row?', '["The PSV row is priced at a fuel price other than USD 870 a tonne, so it cannot be set beside the AHTS row.", "The printed rounded days give 186214.104000 through the engine, 59.996000 short, so the total cannot be reproduced.", "The paper withdrew the PSV row in the edition of 1 February 2024 that the course read on 2026-09-27.", "The engine refuses the PSV month, because its sailing days would need a weather factor above the cap of 10."]'::jsonb, 1, 'Run through the engine, the PSV''s printed rounded days give 186214.104000, which is 59.996000 short of the printed total, so the inputs as printed do not reach the figure printed beside them. The course therefore uses the AHTS row, which reproduces exactly. The PSV month is priced at the same 870 a tonne, nothing was withdrawn, and the engine plans it without a refusal.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 1, 'PSV Ekene Star states a deck area of 800 m2 and a usable deck fraction of 0.75. What deck area capacity does the engine return?', '["600.000000 m2, the stated deck area of 800 m2 times the usable fraction of 0.75.", "800.000000 m2, the whole stated deck, as the fraction trims only the deck load.", "412.5 m2, the capacity the engine gives the AHTS Ekene Tide''s smaller deck at the same fraction.", "540.000000 m2, the deck cargo the Ekene milk run carries, which sets the deck it needs."]'::jsonb, 0, 'The deck area capacity is the stated deck area times the stated usable fraction: 800 times 0.75 is 600.000000 m2. The fraction applies to the deck area only. 412.5 m2 is the AHTS''s capacity from its 550 m2 deck, and 540.000000 m2 is the load on the PSV''s deck.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 2, 'A planner types 1.1 into the usable deck fraction control. What does the engine return?', '["A plan with the fraction held at 1, the whole deck, and a note of the change printed in the reasons.", "A refusal naming vessel.deckAreaM2, since the fraction would claim more deck than the deck area states.", "Refused by name, and the message reads: vessel.deckUsableFraction must be a number above 0 and at most 1; got 1.1", "A plan that reads the extra tenth as cargo stacked on the deck, so the capacity grows by a tenth."]'::jsonb, 2, 'The usable fraction must be above 0 and at most 1, and 1.1 would claim more deck than the vessel has, so it is refused on vessel.deckUsableFraction with the value it got. The engine changes no stated input, the deck area is not at fault, and it stacks no cargo.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 3, 'On the Ekene PSV milk run in the rainy season, the usable deck fraction is changed from 0.75 to 1 and nothing else. Which constraint does the engine name as binding?', '["Deck area, still at 0.900000, since the fraction changes the capacity of no constraint the engine checks.", "Deadweight, at 0.682857, now above the deck area''s 540 of 800 m2 and the highest of all.", "Deck area, at 1.000000, since a usable fraction of 1 means the cargo fills the whole of the deck.", "None: the engine refuses the call, since the usable fraction must stay strictly below 1."]'::jsonb, 1, 'A fraction of 1 is accepted and makes the deck area capacity the full 800 m2. Reading the utilisations, deck area''s 540 of 800 m2 now sits just below the deadweight''s 0.682857, so the deadweight is the highest, and the engine names it. 0.900000 was deck area''s utilisation at 0.75, a fraction of 1 does not fill the deck, and 1 is inside the accepted range.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 4, 'Which capacity constraints does the usable deck fraction reduce?', '["Every constraint on the vessel, so the deck load, the deadweight and each tank are all cut to three quarters.", "The deck area and the deck load together, since both belong to the vessel''s open after deck and neither to its tanks.", "The deadweight alone, as an allowance for the fuel, water and stores the vessel carries for itself.", "The deck area alone; the deck load, the deadweight and the tanks are each a capacity stated in its own right."]'::jsonb, 3, 'The engine''s basis states the rule: deck area capacity is the deck area times the usable fraction. The deck load is stated in tonnes, the deadweight in tonnes and each tank in m3, each as a capacity the call states directly, so the fraction touches none of them.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 5, 'On the Ekene milk run the deck cargo weighs 635.000000 t, and the PSV''s deck load is stated at 2000 t. What utilisation does the engine return for the deck load?', '["0.900000, the deck area''s utilisation, which the engine reports for the deck as a whole.", "0.317500, the deck cargo''s 635 t over the deck load of 2000 t, its own constraint.", "0.682857, the deadweight''s utilisation, since deck weight counts against the deadweight.", "0.620833, the utilisation of the water tank, the fullest of the six tanks on the voyage."]'::jsonb, 1, 'Utilisation is load over capacity: 635 over 2000 is 0.317500. The deck fills by area long before it fills by weight here. 0.900000 is the deck area, 0.682857 the deadweight with the bulk added, and 0.620833 the water tank: each is its own constraint with its own utilisation.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 6, 'On the Ekene milk run, 635.000000 t of deck cargo sails with diesel 460, water 745, mud 200, brine 85, cement 60 and barite 70 m3, at stated densities of 0.85, 1, 1.4, 1.2, 1.5 and 2.1 t a m3. What deadweight load does the engine return?', '["635.000000 t, the deck cargo alone.", "3500.000000 t, the PSV''s deadweight.", "2390.000000 t, the deck weight plus each bulk volume times its density.", "2200 t, the cargo deadweight that the AHTS Ekene Tide states for the same cargo and route."]'::jsonb, 2, 'The deadweight load is the deck weight plus every bulk m3 times its stated density, which the engine returns as 2390.000000 t, a utilisation of 0.682857 against 3500 t. Bulk counts against both its tank and the deadweight. 3500 and 2200 are the two vessels'' capacities.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 7, 'A small case states deck cargo of 5 m2 and 60 t on a deck of 50 m2 usable rated for 80 t, and 50 m3 of a product d at 2.9 t a m3 filling its 50 m3 tank, against a cargo deadweight of 200 t. What does the engine return?', '["A deadweight load of 205.000000 t, overloaded at 1.025000, and returned with its reasons.", "A refusal, since a density above 2.1 t a m3 lies outside the range of the products the engine accepts.", "A deadweight load of 60 t, since bulk carried in the tanks is left out of the cargo deadweight.", "A feasible plan at a deadweight utilisation of 1.000000, since 205 t is read as close enough to 200 t."]'::jsonb, 0, 'The engine''s reasons, verbatim: the binding constraint is deadweight: 205 t of 200 t (102.5%), and overloaded: deadweight needs 205 t against a capacity of 200 t. Any density above 0 is accepted, bulk counts in the deadweight, and a load five tonnes above its capacity is overloaded, with no rounding toward a fit.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 8, 'What does the engine add to the cargo deadweight for stowage or for the vessel''s own stores?', '["A stowage factor of 0.85, the usable share of carrying capacity that Skoko et al. apply to every vessel.", "A fixed allowance for the vessel''s own fuel, water and stores, taken off the stated deadweight before any cargo is counted.", "The unused part of the deck, turned into tonnes at the density of the heaviest product on board.", "Nothing: the cargo deadweight is the planner''s net figure, with no stowage factor and no allowance added."]'::jsonb, 3, 'The engine applies no stowage factor and adds no allowance: every figure it needs is a stated density or a stated capacity. Skoko et al. use a usable share of 85% of carrying capacity, and the course names it as their choice, which enters a call only as a stated input. The engine converts no deck area into tonnes.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 9, 'On the Ekene PSV milk run, which of the six tanks does the engine report as the fullest?', '["The diesel tank, at 0.575000, since diesel is the product the installations ask for most.", "The barite tank, at 0.280000, since barite is the densest of the six products carried.", "The water tank, at 0.620833, still well below the deck area''s 0.900000.", "The mud tank, at 0.333333, the heaviest liquid."]'::jsonb, 2, 'Each tank''s utilisation is its load over its capacity: water is 745 of 1200 m3, 0.620833, the highest of the six. Diesel is 460 of 800, 0.575000. A tank''s utilisation is a volume over a volume, so density plays no part in it; density enters the deadweight.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 10, 'A vessel copied from another job states tanks for five of the six Ekene products and leaves mud out. What does the engine return?', '["A refusal, in its own words: vessel.tanks.mud must be stated for every product (0 when the vessel has no tank for it); got nothing", "The missing mud tank is read as unlimited, so the mud always fits without ever binding.", "A refusal, in its own words: vessel.tanks.mud must be above 0 to carry mud; got nothing", "Mud moved to the deck in portable tanks, using up deck area and deck load for the voyage."]'::jsonb, 0, 'Every product needs a stated tank, stated as 0 when the vessel has none, and a missing tank is refused by name as unstated, whether or not any mud is loaded; the message about carrying mud belongs to a tank stated as 0. A missing tank read as no limit would let a plan carry mud the vessel has nowhere to put, and the engine moves no cargo from tanks to deck.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 11, 'The vessel''s tanks include one keyed methanol, and the call''s products are diesel, water, mud, brine, cement and barite. What does the engine return?', '["A plan that carries the methanol tank empty on every voyage and reports its utilisation as 0.000000 in the constraints table.", "A refusal, in its own words: vessel.tanks.methanol is not a product id; the accepted keys of vessel.tanks are the product ids diesel, water, mud, brine, cement, barite", "A plan that adds methanol as a seventh product at the density of water, 1.000000 t a m3, and checks the tank against it.", "A refusal, in its own words: products[6].densityTPerM3 must be a finite number above 0; got nothing"]'::jsonb, 1, 'A tank key must be one of the call''s product ids, and a key the engine does not read is refused with the full list of accepted keys. The engine creates no product from a tank key and ignores no key silently. Methanol is not a product of this call, and the engine adds no seventh product, so it asks for nothing at products[6].'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 12, 'Cement and barite are stated with the kind dry. How does the engine treat them on a voyage?', '["As deck cargo in tonnes, since dry bulk travels in bags on the open deck of a supply vessel, checked against the deck load.", "Outside the deadweight, since dry bulk is weighed at the installation after it is blown across by air from the tanks.", "Against a single shared tank for all dry bulk, since cement and barite are pumped by air.", "Like any product: a volume in m3 against its own tank, and a weight through its stated density into the deadweight."]'::jsonb, 3, 'Each product states its kind, liquid or dry, and the engine checks every tank the same way: a volume against its capacity, and a weight through the density into the deadweight. Bulk travels in segregated tanks, one product to a tank, so cement and barite each have their own, and neither goes on deck.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 13, 'Why does the engine measure deck cargo as an area in square metres?', '["Deck cargo sits side by side with nothing stacked, an idea taken by concept from Aas, Halskau and Wallace (2009).", "Deck cargo is stacked two high on a supply vessel, so an area stands in for a volume at half its height.", "Skoko et al. print every vessel''s deck capacity in square metres, and the engine reads that table.", "A unit''s weight is unknown until the installation weighs it, so area is the only figure a plan can state."]'::jsonb, 0, 'Containers and baskets are placed side by side and none is stacked, so two units of the same footprint need twice the deck; the engine stacks nothing. The course takes the idea from Aas, Halskau and Wallace by concept. The engine reads no table of vessels, and every deck cargo states its weight in tonnes as well as its area.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 14, 'Loaded with the milk run''s 540 m2 of deck cargo, how does deck area come out on the AHTS Ekene Tide, with its 550 m2 deck and a stated fraction of 0.75?', '["A capacity of 550 m2, so the cargo fits.", "A capacity of 600.000000 m2, the same as the PSV, since the two vessels state the same fraction.", "A capacity of 412.5 m2, so deck area is overloaded at a utilisation of 1.309091.", "A refusal for cargo larger than the deck."]'::jsonb, 2, '550 times 0.75 is 412.5 m2, so 540 m2 of cargo gives 1.309091, and the engine''s reason says so: the binding constraint is deck area: 540 m2 of 412.5 m2 (130.909091%). The fraction applies to each vessel''s own deck, and an overloaded voyage is a result with its reasons.'),
  ('marine', 'beginner', 'module', 'm04-deck-and-bulk-capacity', 15, 'The engine checks deck cargo as an area bound. Which of these does it leave unchecked?', '["Whether the deck cargo''s weight stays within the deck load the vessel states in tonnes for its open after deck.", "Whether a unit''s length fits across the deck, a clear lane for the crane, or the balance of the load.", "Whether the deck cargo''s footprint stays within the deck area times the usable fraction the vessel states.", "Whether each product''s bulk volume stays within that product''s own stated tank."]'::jsonb, 1, 'The area bound compares the deck cargo''s area with the usable deck and its weight with the deck load, and the tanks are checked product by product. It does not compare a length with the deck''s width, keep a crane lane or balance the load: a cargo that fits by area can still fail on the real deck, and the deck crew''s plan decides that.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 1, 'Deck area is measured in m2 and a water tank in m3. How can the engine rank the two against each other?', '["It turns every tank volume into square metres of deck at a stated tank height, then compares areas.", "Every load is turned into tonnes through the stated densities, and the constraints are ranked by weight.", "Each utilisation is the constraint''s load over its own capacity, a ratio with no unit.", "It ranks the raw loads, as deck and tanks share one scale."]'::jsonb, 2, 'Utilisation is load over capacity, so 540 of 600 m2 of deck area and 745 of 1200 m3 of water both become plain ratios, 0.900000 and 0.620833, and can be ranked. The engine converts no volume to area, uses densities only for the deadweight, and has no common scale for raw loads.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 2, 'What does the engine name as a voyage''s binding constraint?', '["The constraint with the highest utilisation, with a tie at twelve digits going to the first in the stated order.", "The constraint whose load is the largest figure in its own unit.", "Any constraint at a utilisation of 1.000000 or above, and no constraint at all on a voyage with room on every limit.", "The constraint a regulation requires the vessel to respect, as the word binding is used in contracts, charters and law."]'::jsonb, 0, 'In this course binding means the constraint with the highest utilisation, by the stated tie rule, and the engine names one on every voyage. Loads in different units cannot be ranked, a binding constraint need not be full, and the word carries no legal meaning here.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 3, 'On a small teaching voyage, deck area is 25 of 50 m2, deck load 40 of 80 t, deadweight 50 of 200 t and the one tank 10 of 50 m3. Which constraint is named binding?', '["Deck load, at 0.500000, the last of the two tied constraints in the stated order of checks.", "Both deck area and deck load, since the engine names every constraint that shares the top utilisation.", "None, as nothing is near its limit.", "Deck area, at 0.500000, the first of the two tied constraints in the stated order."]'::jsonb, 3, 'Deck area and deck load share a utilisation of 0.500000, and the engine names the first in the order deck area, deck load, deadweight, tanks: its reason reads the binding constraint is deck area: 25 m2 of 50 m2 (50%). Giving the tie to the last, deck load, is the alternative the course names. The engine names one constraint on every voyage.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 4, 'In what order does the engine list and check a voyage''s capacity constraints?', '["The tanks first, product by product, then the deadweight, then the deck load, and the deck area last of all.", "Deck area, deck load, deadweight, then one tank per product in the order the products are listed.", "Alphabetically by the name of each constraint, so the barite tank is checked ahead of the deck.", "From the highest utilisation to the lowest, so the binding constraint is always the first row."]'::jsonb, 1, 'The stated order is deck area, deck load, deadweight, then the tanks in the order of the products. That order is what the tie rule uses, so it matters: a tie goes to the first constraint in it. The constraints table keeps that order whatever the utilisations are.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 5, 'One tank of 50 m3 holds 45 m3 of a product d at 1 t a m3; the deck carries 5 m2 against 50 m2 usable and 4 t against an 80 t rating; the vessel''s deadweight is 200 t. Which limit does the engine report?', '["Deck area, since it is checked first.", "Deadweight, since bulk adds to it.", "None, since the voyage is feasible and a binding constraint is named only on an overloaded voyage.", "Tank d, at 0.900000, the fullest of the four constraints."]'::jsonb, 3, 'The engine''s reason reads: the binding constraint is tank d: 45 m3 of 50 m3 (90%). A tank is a constraint like any other, and when it is the fullest it binds. The deadweight here is 49 t of 200 t, far below the tank, and a binding constraint is named on every voyage, feasible or not.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 6, 'Every figure lands exactly on its limit: 50 m2 of cargo for 50 m2 of usable deck, 80 t for an 80 t deck rating, and 50 m3 of a 1 t a m3 product filling a 50 m3 tank, with a 200 t deadweight. What comes back?', '["A feasible voyage, with deck area binding at 1.000000: a load exactly at its capacity fits.", "An overloaded voyage on deck area, deck load and the tank, since a load at capacity leaves no margin at all.", "A feasible voyage with the tank binding at 1.000000, since the last of the tied constraints is the one named.", "A refusal: three ties cannot be ranked."]'::jsonb, 0, 'A constraint is overloaded only when its load is above its capacity at twelve digits, so a load exactly at capacity is feasible, and the three-way tie goes to the first in the order, deck area. The engine''s reason: the binding constraint is deck area: 50 m2 of 50 m2 (100%). Reading a load at capacity as overloaded is the alternative the course names.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 7, 'Every limit holds but one: a deck rated for 80 t is handed 81 t. The footprint exactly fills the usable deck, the single tank is full, and the deadweight has room to spare. What is the engine''s verdict?', '["Feasible: one tonne is within the tie rule.", "A voyage that is not feasible, with deck area binding at 1.000000 as the first in the order.", "A voyage that is not feasible, with deck load binding at 1.012500 and named as overloaded.", "A refusal naming the deck cargo''s weight."]'::jsonb, 2, 'Deck load is at 1.012500, above every other utilisation, so it binds; its load is above its capacity, so it is overloaded. The engine''s reasons: the binding constraint is deck load: 81 t of 80 t (101.25%) and overloaded: deck load needs 81 t against a capacity of 80 t. The tie rule acts at twelve digits and one tonne is far beyond it; the tie order applies only to equal utilisations; and an overload is a result.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 8, 'Two deck cargoes of 0.1 and 0.2 m2 fill a 0.3 m2 deck area capacity. Held as binary doubles, the sum comes back a hair above 0.3 and the utilisation a hair above 1. What does the engine return?', '["An overloaded voyage on deck area, since a utilisation a hair above 1 is above 1 however small the excess.", "Feasible: compared at twelve digits the sum equals the 0.3 m2 exactly, so deck area binds at 1.000000.", "A refusal: a footprint below 1 m2 is too small.", "A feasible voyage, since the engine rounds every load to six decimals before any capacity check."]'::jsonb, 1, 'Decimal inputs are held as binary doubles, so the sum lands a hair above 0.3. The engine compares at twelve significant digits, where the load equals the capacity, so the voyage is feasible. Without the rule, rounding noise would decide the answer. The engine accepts small cargo, and six decimals is only how figures are printed.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 9, 'The Ekene milk run''s deck cargo is doubled to 1080 m2 on the PSV''s 600.000000 m2 of usable deck. What does the engine return?', '["A full voyage plan with its hours and fuel, marked infeasible, deck area binding at 1.800000 and named as overloaded.", "A refusal, since a deck cargo of twice the usable deck is an input the engine cannot plan with at all.", "A plan split into two voyages of 540 m2 of deck cargo each, both with deck area binding at 0.900000.", "A plan that carries the first 600 m2 of deck cargo and leaves the rest at the base for the next voyage."]'::jsonb, 0, 'An overloaded voyage is a result: the engine returns its hours, days and fuel, which do not depend on whether the cargo fits, and adds the verdict and the reasons, here overloaded: deck area needs 1080 m2 against a capacity of 600 m2. It splits no voyage and leaves no cargo behind; those are the planner''s answers.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 10, 'The Ekene milk run''s cargo is put on the AHTS Ekene Tide. Which constraints does the engine name as overloaded?', '["Deck area alone, since the reasons name only the binding constraint of the voyage.", "Deck area, deck load and deadweight, the three constraints the open deck carries.", "Deck area, deadweight and tank water, with deck area binding at 1.309091.", "Every constraint on the AHTS, since an overloaded voyage is overloaded throughout."]'::jsonb, 2, 'The reasons list the binding constraint and then every other overloaded one: deck area at 540 of 412.5 m2, deadweight at 2390 of 2200 t, and tank water at 745 of 600 m3. The deck load, 635 t against 1200 t, is inside its capacity, and so are the other five tanks.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 11, 'On the Ekene milk run, the PSV''s brine tank is stated as 0 while the jack-up asks for 85 m3 of brine. What does the engine return?', '["An overloaded voyage, with tank brine binding and a utilisation too large to print as a finite figure.", "A refusal, in its own words: vessel.tanks.brine must be stated for every product (0 when the vessel has no tank for it); got 0", "A voyage that leaves the brine at the base and names it in the reasons as cargo not carried.", "A refusal, in its own words: vessel.tanks.brine must be above 0 to carry brine: the installations on the milk run ask for 85 m3 of it; got 0"]'::jsonb, 3, 'A load of a product the vessel has no tank for is refused by name, with the tank, the product, the m3 the stops ask for and the value it refused. There is no finite utilisation over a zero capacity, so it is no overload. The brine tank is stated, as 0, so the message for a tank left out does not apply, and the engine drops no cargo from a plan.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 12, 'Why does the engine refuse a load of a product whose tank is stated as 0, where it plans an overloaded deck as a result?', '["A tank of 0 is always a typing slip, so the engine asks for the tank to be typed again before it plans.", "A load over a capacity of zero has no finite utilisation, and no voyage of that vessel could carry the product.", "A deck can take extra cargo by stacking units two high, where a tank has no such room to give.", "Bulk is priced per m3 where deck cargo is priced per m2, so the fuel bill cannot be worked out."]'::jsonb, 1, 'An overload reports a ratio and names what another voyage or a larger vessel could fix; a zero tank has no ratio and no voyage of that vessel can carry the product, so the fix lies outside the voyage. A tank of 0 is a valid statement that the vessel has no tank, the engine stacks no cargo, and it prices fuel only.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 13, 'A vessel states a tank of 0 for a product d, and no installation asks for any d. What does the engine return?', '["A refusal, since every tank a vessel states must be above 0 whether or not it is used on the voyage.", "A refusal asking for product d to be removed.", "A feasible plan, with the empty zero tank reported at a utilisation of 0.000000.", "A plan that drops tank d from the table."]'::jsonb, 2, 'A zero tank is how a vessel states it has no tank for a product, and it is accepted as long as nothing is loaded into it. The engine reports its utilisation as 0.000000 in the constraints table. Only a load of that product is refused, and a product nobody asks for may stay in the call.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 14, 'The course advises reading a voyage plan''s feasible flag before any other figure. Why?', '["An overloaded voyage still returns its hours, days and fuel, so those figures alone do not show whether the cargo fits.", "The engine prints hours and fuel only for a feasible voyage, so the flag says whether any hours follow.", "The flag carries the binding utilisation, and every other figure in the plan is computed from it in turn, hours and fuel included.", "A voyage that is not feasible is refused, so the flag says whether any figure follows at all."]'::jsonb, 0, 'The engine plans an overloaded voyage in full, hours, days and fuel included, and marks it with the verdict and the reasons. Reading the time and cost first can hide that the cargo does not fit. The binding utilisation is its own field, and an overload is a result with no refusal.'),
  ('marine', 'beginner', 'module', 'm05-the-binding-constraint', 15, 'The engine''s reason reads: the binding constraint is deck area: 540 m2 of 600 m2 (90%). Which figure does the course quote for the utilisation?', '["90%, the percentage the reason prints, since the reason is the engine''s own words.", "0.9, the short figure, since the engine drops trailing zeros in every figure.", "540 over 600 as a fraction, since a utilisation is written as load over capacity.", "0.900000, the numeric field beside the reason, to six decimals."]'::jsonb, 3, 'A reason prints short figures and a percentage; the numeric field keeps full precision and the course quotes it to six decimals, 0.900000. Trailing zeros are dropped only inside the engine''s sentences, and a utilisation is quoted as the figure the engine returns.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 1, 'The PSV (11 knots) and the AHTS (12 knots) sail the Ekene milk run with the same cargo, port and field hours, and 1.2 on sailing and field time. What total hours does the engine give the AHTS?', '["62.072727, the same as the PSV, since both vessels sail the same 206.000000 NM of legs.", "60.200000, fewer than the PSV because the AHTS sails faster.", "64.472727, since the AHTS''s anchor-handling role adds the weather factor to its port time.", "53.727273, the calm voyage''s hours."]'::jsonb, 1, 'The AHTS covers the 206.000000 NM at 12 knots, so its sailing hours are fewer, and with the same port and field hours its voyage is 60.200000 hours against the PSV''s 62.072727. The weather input is the same for both and names no port time, and the engine applies it whatever the vessel''s speed.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 2, 'On the Ekene milk run the AHTS burns 23.880000 t against the PSV''s 19.876364 t, though its voyage is shorter. Why?', '["It sails a longer route, since the AHTS''s milk run adds a leg out to an anchor-handling site.", "Its weather factor is higher, since the engine slows an AHTS more than a PSV in the same swell and the same rainy season.", "Its fuel is priced higher, since the engine charges an AHTS at a different price a tonne.", "It burns more an hour in every activity: 0.600000, 0.040000 and 0.400000 t against the PSV''s 0.500000, 0.030000 and 0.300000."]'::jsonb, 3, 'Fuel is hours by activity times the stated burn for each activity. The AHTS''s stated burns are higher in all three, so it burns more fuel in all even over fewer hours. The two vessels sail the same legs under the same weather input, and the price enters the cost and leaves the tonnes alone: the fuel cost is 20775.600000 against 17292.436364 at the same 870.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 3, 'The Ekene milk run''s cargo is planned on both vessels in the rainy season. Which vessel makes a plan, by the engine''s results?', '["The AHTS: its 60.200000 hours are the shorter voyage, and the shorter voyage is the better plan whatever load it carries.", "The AHTS: its fuel cost of 20775.600000 is the lower of the two bills for the same cargo on the same route.", "The PSV: it carries the cargo with deck area binding at 0.900000, where the faster AHTS is overloaded at 1.309091.", "Neither vessel, since the reasons show both of them overloaded on deck area on this milk run."]'::jsonb, 2, 'The PSV''s voyage is feasible and the AHTS''s is overloaded on deck area, deadweight and tank water. A faster voyage that does not fit is no plan. The AHTS''s bill is the higher one, 20775.600000 against 17292.436364, and the PSV is feasible with room on every constraint.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 4, 'The AHTS voyage on the Ekene milk run is re-run in calm weather, a factor of 1. Does the engine then call it feasible?', '["No: weather changes time and fuel only, so deck area, deadweight and tank water stay overloaded.", "Yes, since a calm voyage burns less fuel, and the saved fuel frees deadweight for the cargo the tanks hold.", "Only on deck area, since calm weather frees the crane''s working space on the open deck.", "It depends on the fuel price, since a cheaper voyage can carry more cargo within its budget."]'::jsonb, 0, 'The capacities and loads are the same in calm weather and in the rainy season, so the verdict does not move: the engine still names deck area binding at 1.309091 with deadweight and tank water overloaded. The vessel''s fuel is not part of the cargo deadweight, the usable fraction is a stated input, and the price enters only the fuel cost.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 5, 'How long, in days, is one PSV voyage round the four Ekene stops with a factor of 1, and how long with the 1.2 allowance on sailing and field time?', '["2.586364 days in both seasons.", "2.238636 days calm and 2.686364 days in the rainy season, with the base''s port time slowed too.", "2.238636 days calm and 2.586364 days in the rainy season.", "53.727273 and 62.072727 days."]'::jsonb, 2, 'A voyage''s days are its total hours after the weather factor, over 24: 53.727273 calm hours are 2.238636 days and 62.072727 rainy-season hours are 2.586364 days. 2.686364 is the rainy-season voyage with port time named as well, which this plan does not state, and 53.727273 and 62.072727 are hours.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 6, 'Which checks on the course''s pre-sailing checklist does the engine enforce for the planner, refusing an input that breaks one?', '["The reading checks: whether the voyage is feasible, which constraint binds and whether the voyage''s days fit the vessel''s time.", "The input checks: a tank and density for every product, each stop named once with one more leg than stops, and a stated weather input.", "Every check on the list, so a plan the engine accepts without a refusal is ready to sail as it stands.", "None of them, since the engine plans whatever it is given and reports any fault in the reasons afterwards."]'::jsonb, 1, 'The first three checks are about inputs, and an input that breaks one is refused by name. The last four are about reading the result, the verdict, the binding constraint, the days and the fuel with its price, and only the planner can make them: an overloaded voyage is a result and the engine knows no period at this tier.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 7, 'Why does the checklist leave it to the planner to confirm that a voyage''s days fit the time the vessel has?', '["A voyage plan states no period, so the engine reports the days without knowing how long the vessel is available.", "The engine rounds a voyage''s days up to whole days, so the planner must work out the exact days by hand.", "The engine refuses any voyage longer than one day, so a voyage it plans always fits inside the vessel''s available time.", "A voyage''s days depend on the fuel price, which the engine is not given at this tier of the course."]'::jsonb, 0, 'voyagePlan reads no period and no available days, so it cannot compare the days with the vessel''s time; the Professional tier states them. The engine rounds no days, plans voyages of any length (the Ekene milk run is 2.586364 days), and the days follow from the hours alone.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 8, 'A colleague quotes the rainy-season Ekene fuel cost as 17292.436364. What must the quote name beside the figure, by the course''s rule?', '["The date the fuel price was read, since the engine can confirm every other input on its own from its tables.", "The binding constraint of the voyage, since the fuel cost depends on which constraint binds the plan.", "The deck area capacity, since the engine burns fuel for each square metre of cargo carried.", "The fuel burns, the price of 870 a tonne, and the weather factor with the activities it slows."]'::jsonb, 3, 'A figure that depends on an input is quoted with it: a fuel cost with its burns and price, and the hours under it with the route, speed and weather. The weather choice alone moves the bill by 2829.872727. The binding constraint and the deck area do not enter the fuel, and the engine confirms no input for the planner.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 9, 'Which question does this tier''s voyage plan leave to the procurement course?', '["Which vessel carries a stated cargo on a stated route within its capacities.", "Which vessel a company should hire for the work, and at what day rate or contract.", "How long a voyage takes at a stated speed, with its port and field hours.", "What a voyage''s fuel costs at a stated burn for each activity and a stated price."]'::jsonb, 1, 'The engine answers which vessel carries a stated cargo on a stated route, how long the voyage takes and what its fuel costs. It sets no hire rate and prices no contract: vessel hire and contracting belong to the procurement course.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 10, 'Which sentence uses the word utilisation as this course requires?', '["The PSV runs at a utilisation of 0.900000 on the Ekene milk run in the rainy season.", "The rainy-season voyage has a utilisation of 0.900000, which leaves the vessel some room.", "Utilisation across the Ekene cluster is high this season, at about 0.900000 of the whole.", "The deck area''s utilisation on the Ekene PSV milk run is 0.900000."]'::jsonb, 3, 'In this course a utilisation is always of a named thing: a constraint here, and at later tiers a deck, the fleet or a berth. 0.900000 is the deck area''s utilisation; the other constraints have their own, from 0.212500 for the brine tank to 0.682857 for the deadweight, so a vessel, a voyage or a cluster has no single utilisation.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 11, 'A planner is drafting a line on how much the PSV can carry. Which draft meets the course''s rule for capacity?', '["The PSV''s deadweight capacity is 3500 t, and the Ekene milk run loads 2390.000000 t against it.", "The PSV has plenty of capacity left over for the Ekene milk run in the rainy season, whatever the cargo.", "The AHTS lacks the capacity for this route, so a second vessel will be needed on each voyage.", "Capacity is what the Ekene cluster needs more of when the rainy season comes."]'::jsonb, 0, 'A capacity is always of a named constraint: deck area times the usable fraction, deck load, deadweight or a named tank. The PSV has 600.000000 m2 of deck area capacity and 3500 t of deadweight, each with its own utilisation, so a sentence that names no constraint says nothing a plan can check.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 12, 'The AHTS''s reasons on the Ekene milk run name three overloaded constraints. Which changes do those reasons point a planner toward?', '["Raising the weather factor until the voyage takes long enough for the cargo to be worked alongside.", "Lowering the fuel price, since a cheaper voyage frees deadweight for more of the cargo on deck.", "Moving some cargo to another voyage, choosing the larger vessel, or splitting the milk run.", "Stating a usable deck fraction above 1, so that the same deck holds more of the cargo."]'::jsonb, 2, 'An overloaded voyage is a result that names what does not fit, so the fixes are about the cargo, the vessel or the route. The weather factor and the fuel price change time and money and leave every capacity where it is, and a usable fraction above 1 is refused by name.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 13, 'Why is the comparison of the two Ekene vessels on the milk run a fair one?', '["Both vessels state the same speed, so every difference between the two rows comes from the tanks.", "The engine scales each vessel to the same deck before it compares them, so the decks cancel out.", "Both are run in calm weather, so the weather cannot favour one of the two vessels over the other.", "Only the vessel changes: route, cargo, port and field hours, weather input and price are the same in both."]'::jsonb, 3, 'Every difference in the table comes from the vessels'' own stated figures because nothing else changed. The PSV states 11 knots and the AHTS 12, the engine scales nothing, and both rows carry the rainy-season factor of 1.2 on sailing and field time. Change the weather on one side and the comparison would mix two effects.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 14, 'On the Ekene PSV milk run the deck area''s utilisation is 0.900000 and the deadweight''s 0.682857. What does that pair tell a planner?', '["Deck area runs out first, so the vessel has more room by weight than by area for dense, compact cargo.", "Deadweight binds, since it is the constraint nearest to its limit when the limits are counted in tonnes.", "The voyage is overloaded by weight, since 0.682857 of the 3500 t deadweight is above the 2000 t deck load.", "Nothing a planner can use, since the utilisations of two constraints in different units cannot be compared."]'::jsonb, 0, 'The binding constraint is the highest utilisation, deck area at 0.900000, and the deadweight comes second. The gap says where room is left: by weight more than by area. Utilisations are unitless ratios, so they compare across units; the deadweight load of 2390.000000 t is checked against the 3500 t deadweight, and the deck load is its own constraint at 0.317500.'),
  ('marine', 'beginner', 'module', 'm06-planning-a-voyage-end-to-end', 15, 'On the rainy-season Ekene PSV plan, the fuel price control is changed from 870 to 0. What does the engine return?', '["A refusal, since the fuel price must be a finite number above 0 for the fuel to be costed at all.", "No fuel and no cost at all.", "The same hours and the same 19.876364 t of fuel, with a fuel cost of 0.000000.", "The same fuel cost of 17292.436364, since a price of zero is replaced by Skoko et al.''s USD 870."]'::jsonb, 2, 'A fuel price must be a finite number at or above 0, so 0 is accepted. Fuel follows the hours and the burns, so the tonnes do not move, and the cost is the tonnes times the stated price, which is now 0. The engine replaces no stated input with a published figure.'),
  ('marine', 'beginner', 'final', null, 1, 'What is the largest weather factor the engine accepts, and where does that limit live?', '["1.2, the rainy-season allowance of the Ekene fixture, which the engine treats as the worst weather it plans.", "50, the same cap as MAX_INSTALLATIONS, since both limits guard the size of one call to the engine.", "10, held as MAX_WEATHER_FACTOR in the engine''s DEFAULTS; the smallest factor accepted is 1.", "There is none: any finite factor above 1 is accepted, since the weather is always the planner''s input."]'::jsonb, 2, 'DEFAULTS holds the engine''s caps and its tie rule, and MAX_WEATHER_FACTOR is 10; a factor of 10.5 is refused and so is 0.9. The Ekene 1.2 is one stated planning factor, and 50 is the cap on installations, a different limit.'),
  ('marine', 'beginner', 'final', null, 2, 'A vessel box names its deck area with the key deckArea. What does the engine return?', '["A refusal, in its own words: vessel.deckArea is not an accepted key; the accepted keys of vessel are name, speedKnots, deckAreaM2, deckUsableFraction, deckLoadT, deadweightT, tanks, fuelTPerHour", "A plan that reads deckArea as the deck area in m2, since the engine matches a key it does not know to the nearest accepted key it has and plans on.", "A refusal, in its own words: vessel.deckAreaM2 must be a finite number above 0; got nothing", "A plan that sets deckArea aside and carries on, planning the deck with no area limit on the deck cargo at all."]'::jsonb, 0, 'Every call checks its accepted keys first and refuses a key it does not read, at whatever level it sits, with the path and the full list of accepted keys. Because the unknown key is checked before any missing input, the refusal names deckArea. The engine guesses no key and drops none silently.'),
  ('marine', 'beginner', 'final', null, 3, 'The Wikipedia article on first-fit decreasing, revision 1317275412, is licensed CC BY-SA 4.0. How does the course use it?', '["It reproduces the article''s paragraphs under the share-alike terms, crediting the article beside each lesson.", "It teaches the article by concept only, as it does a publisher''s paper, without naming a revision at all.", "It leaves the article out, since a page that anyone can edit cannot be cited in a course.", "It cites the rule and the examples by section and example, and pastes none of the article''s wording."]'::jsonb, 3, 'A CC BY-SA text is cited without pasting its wording, and the course names the revision because a living page changes over time. Concept-only use is for the publisher''s paper. The article is cited, with its revision of 17 October 2025.'),
  ('marine', 'beginner', 'final', null, 4, 'Why does the course name each source''s edition and the date it was read?', '["The licence of each text runs out a set time after it is read, so the date shows the licence was still valid.", "Notes are revised, a handbook stays in draft and a web page is edited, so a check can only be repeated against the same text.", "The engine reads each source again whenever it runs, and the date tells it which copy of the text to load.", "Suite rules require the dates, and the Marine Logistics Planner prints them on its opening screen beside each figure it quotes from a source."]'::jsonb, 1, 'A figure checked against one edition may not match the next, so naming the edition and the date read, 2026-09-27 for every text, lets anyone repeat the check. The engine carries its citations in its own words and reads no source at run time, and the dates are the course''s own record.'),
  ('marine', 'beginner', 'final', null, 5, 'Which three names does the engine''s exported ACTIVITIES list hold?', '["sailing, port and field, each with its own stated fuel burn and each open to the weather factor.", "sailing, loading and standby, the three states a supply vessel''s log records on a voyage.", "transit, alongside and waiting on weather, with the weather held apart as an activity of its own.", "sailing, port, field and standby, with standby burning fuel at the port rate unless stated."]'::jsonb, 0, 'ACTIVITIES is sailing, port and field: the three kinds of time a voyage spends, each with its own burn, and the names weather.appliesTo may list. Standby is refused as an activity, and the engine models no waiting on weather; a planner states such time inside the port or field hours.'),
  ('marine', 'beginner', 'final', null, 6, 'What does the basis block that comes back with every result give a learner?', '["A list of the Suite screens where the same figures appear, so a learner can find them in the planner.", "The figures the engine filled in for any input the call left out, with the source of each one.", "A margin of error for each figure, taken from the rounding of the published tables.", "The rules the call applied and the source of each, in the engine''s own words, to print beside the figures."]'::jsonb, 3, 'Every result carries a basis naming its rules and their sources, for example that sailing hours are the distance over the speed, citing Skoko et al. The engine fills in no missing input, since a call without one is refused, it prints no error margins, and the basis describes the call and no Suite screen.'),
  ('marine', 'beginner', 'final', null, 7, 'Where does the Ekene cluster come from, as its own file declares?', '["It is a sample of a real operator''s supply records, released for teaching with the names removed.", "It is the worked example of Aas, Halskau and Wallace (2009), restated on four installations.", "A stated script wrote it for this platform as SYNTHETIC data for the fictional Ekene field, block EK-11.", "A public dataset from an offshore regulator, licensed for reuse with credit to the regulator that published it for training."]'::jsonb, 2, 'The file''s own statement calls the data SYNTHETIC, for Petrolord''s fictional teaching field, block EK-11, set in a fictional offshore cluster. It is nobody''s operating record, it restates no paper''s example, and no regulator published it.'),
  ('marine', 'beginner', 'final', null, 8, 'On the rainy-season dedicated route, the EKA voyage takes 32.727273 hours. Which part of those hours does the weather allowance of 1.2 on sailing and field time leave as stated?', '["The 13.527273 sailing hours out and back.", "The 12.000000 port hours at the base.", "The 7.200000 field hours alongside EKA, since a dedicated voyage works one installation only.", "None of them: on a dedicated voyage the factor applies to every hour of the voyage."]'::jsonb, 1, 'Only the named activities are multiplied, and the plan names sailing and field time, so port time stays at the stated 12.000000 hours. The sailing hours, 13.527273, and the field hours, 7.200000 from a stated 6, both carry the factor; a dedicated route reads the weather input exactly as a milk run does.'),
  ('marine', 'beginner', 'final', null, 9, 'Of the four Ekene dedicated voyages in the rainy season, which takes the most days, and why?', '["EKJ, because the jack-up''s 8 field hours are the longest call in the cluster.", "EKA, because it is the first installation the milk run calls at.", "EKB, because the wellhead platform has the fewest field hours to fill.", "EKF, because it lies farthest from the base, at 95.000000 NM."]'::jsonb, 3, 'Every dedicated voyage pays the same 12 port hours, so distance decides most of the gap: EKF''s 190.000000 NM out and back take 20.727273 sailing hours, for 1.613636 days. EKJ takes 1.518182 days, its longer field time not making up for its shorter distance, and EKA at 1.363636 and EKB at 1.372727 are the two shortest voyages.'),
  ('marine', 'beginner', 'final', null, 10, 'A planner reverses the order of the Ekene milk run''s stops, to EKF, EKB, EKJ, EKA. What must happen to the legs?', '["They must be restated to match, since each leg is the distance from the point before it to the point after it.", "Nothing: the engine re-sorts the stated legs to follow the new order of stops on its own.", "The engine reads the stated legs backwards whenever the stops are reversed, so they still fit.", "The engine refuses the reversed order, since it accepts only the order the fixture was written in."]'::jsonb, 0, 'The engine reads the stops in the order stated and the legs in the same order, so it cannot know the distance from EKB to EKJ unless the call gives it. It re-sorts nothing and reverses nothing, and any order that names each stop once is accepted with its own legs.'),
  ('marine', 'beginner', 'final', null, 11, 'The third leg of the Ekene milk run is typed as -12 NM. Which field does the engine''s refusal name, and what does the leg have to be?', '["The leg is read as 12 NM and the voyage planned, since a distance has no direction on a milk run.", "route.stops[2], the stop that the negative leg sails toward, which must then be restated.", "route.legsNm[2], the third leg counted from 0, where any distance from 0 NM up is accepted.", "The leg is treated as 0 NM, the smallest distance the engine accepts, as if two stops shared one place."]'::jsonb, 2, 'The engine''s own words: route.legsNm[2] must be a finite number at or above 0; got -12. The list is counted from 0, so the third leg is route.legsNm[2]. The engine changes no stated figure to make it fit, and the stops are not at fault.'),
  ('marine', 'beginner', 'final', null, 12, 'On a dedicated route, the first installation in the call states no distanceFromBaseNm. Which input does the refusal point the planner to?', '["route.legsNm, since a dedicated route with a missing distance takes it from the legs as a milk run does.", "installations[0].distanceFromBaseNm, the distance the dedicated voyage sails out and back.", "route.mode, since a dedicated route with a missing distance must have been meant as a milk run.", "No input: the engine sails the installation at 0 NM, as if it stood right beside the base."]'::jsonb, 1, 'The engine''s own words: installations[0].distanceFromBaseNm must be a finite number at or above 0; got nothing. A dedicated voyage sails each installation''s stated distance out and back, and that distance is required with no assumed value. Legs are read only on a milk run, and the route mode is a stated input the engine does not second-guess.'),
  ('marine', 'beginner', 'final', null, 13, 'A dedicated route box still carries the stops list from an earlier milk run. What happens?', '["The plan runs on the dedicated route and sets the unused stops aside without mentioning them anywhere in the result.", "The plan sails the stops as a milk run, since a stops list is taken to override the stated route mode.", "The refusal names route.legsNm, since a stops list without legs is incomplete on any route mode the engine plans.", "The stops list is refused by name, since only a milk run reads stops; a dedicated voyage sails to one installation and back."]'::jsonb, 3, 'Each route mode reads its own inputs, and an input given to the mode that does not read it is refused by name, so nothing is set aside silently and nothing switches the mode. The engine''s words begin: route.stops is read only when route.mode is "milk-run".'),
  ('marine', 'beginner', 'final', null, 14, 'On the rainy-season Ekene milk run, which activity takes the most hours?', '["Sailing, at 22.472727 hours, since the vessel covers 206.000000 NM between the base and the stops.", "Port time, at 12.000000 hours, since loading at the base is the longest single task of a voyage.", "Field time, at 27.600000 hours, more than the 22.472727 hours of sailing.", "Sailing and field time equally, since the factor of 1.2 applies to both of them at once."]'::jsonb, 2, 'With the factor on sailing and field time, field time is 27.600000 hours and sailing 22.472727, so the vessel spends more hours alongside the installations than sailing between them, as in a compact cluster. Port time is 12.000000 hours, and the same factor on two activities leaves their hours in the same proportion as their calm times.'),
  ('marine', 'beginner', 'final', null, 15, 'Why does the engine keep sailing, port and field time apart, where it could add them into one figure?', '["Each activity has its own stated fuel burn, and each can be named on its own in the weather list.", "Each activity is charged a different price a tonne, so the fuel bill needs them kept apart.", "Each is rounded to whole hours separately before the three are added into the total.", "Each is checked against its own capacity in hours, like the deck area and the tanks of a vessel are checked against theirs."]'::jsonb, 0, 'Fuel is hours by activity times that activity''s burn, and weather.appliesTo names which of the three the factor slows, so the engine needs the hours of each. The fuel price is one stated price, the engine rounds no hours, and an activity is a time with no capacity of its own.'),
  ('marine', 'beginner', 'final', null, 16, 'The calm Ekene milk run (factor 1) burns 9.363636 t sailing, 0.360000 t in port and 6.900000 t at the field. At 870 a tonne, what does the engine return in all?', '["19.876364 t of fuel, costing 17292.436364, the plan with 1.2 on sailing and field time.", "19.948364 t, costing 17355.076364.", "16.623636 t, costing 17292.436364.", "16.623636 t of fuel, costing 14462.563636."]'::jsonb, 3, 'The three fuels add to 16.623636 t, and at 870 a tonne that is 14462.563636. The rainy-season plans burn more because the factor adds hours, and a cost is always the tonnes of its own plan times the stated price.'),
  ('marine', 'beginner', 'final', null, 17, 'Of sailing, port and field, where does the rainy-season PSV voyage round the Ekene stops burn the most tonnes?', '["Field time, 8.280000 t, since the vessel spends more hours alongside than at sea.", "Sailing, 11.236364 t of the 19.876364 t, though field time takes more hours.", "Port time, 0.360000 t, since the base''s 12 hours come before any sailing.", "Sailing and field time equally, since the factor of 1.2 applies to both of them."]'::jsonb, 1, 'Field time is the longest activity, 27.600000 hours against 22.472727 sailing, but it burns 0.3 t an hour against sailing''s 0.5, so it burns 8.280000 t against 11.236364 t. Port burns 0.03 t an hour. Fuel is hours times each activity''s own burn, so equal factors do not make equal fuel.'),
  ('marine', 'beginner', 'final', null, 18, 'In the Skoko et al. Table 1 check, a PSV at 10 knots sails a dedicated voyage of 120 NM each way at a weather factor of 1. What sailing hours does the engine return, and which printed figure do they confirm?', '["12.000000 hours for the voyage, since each 120 NM leg at 10 knots is sailed in half a day and the legs overlap in the table.", "24.000000 hours for 264.000000 NM, the distance Skoko et al. print for a PSV''s day at sea.", "24.000000 hours for 240.000000 NM, the 240 NM a day Skoko et al. print for a PSV at its economic speed.", "22.472727 hours, since a rainy-season factor of 1.2 is applied to the day''s sailing before it is compared."]'::jsonb, 2, '240 NM at 10 knots is 24.000000 hours, a day of sailing, and Skoko et al. print 240 NM a day for a PSV (their Table 4). Each leg takes 12 hours, so the voyage takes 24, and the check states a factor of 1, so no allowance applies. 264 NM is the AHTS figure, which the engine confirms at 11 knots over 132 NM each way.'),
  ('marine', 'beginner', 'final', null, 19, 'A planner raises the weather factor on sailing. Through what does the engine''s fuel figure move?', '["Only through the hours it adds: each extra hour burns at the stated rate of its activity.", "It multiplies the burn rates as well as the hours, so fuel grows with the square of the factor.", "A fixed tonnage of fuel is added to each voyage for rough water, whatever the voyage''s hours.", "It raises the fuel price a tonne in the rainy season, in proportion to the stated factor."]'::jsonb, 0, 'The factor multiplies the time of the named activities; fuel is hours times the stated burn, so fuel rises only with those hours. The engine has no speed-cube law and no curve of fuel against weather, adds no fixed tonnage, and it leaves the stated price as it is.'),
  ('marine', 'beginner', 'final', null, 20, 'Which features of the weather does the engine itself model?', '["A weather window, opening and closing the voyage by the forecast for the stated season.", "Wave height, turned into a speed loss through a curve of speed against the sea state.", "Waiting on weather at an installation, added as standby hours whenever the factor exceeds 1.", "Only one stated factor on the stated activities; no weather window, wave height or waiting rule."]'::jsonb, 3, 'Aas, Halskau and Wallace describe weather limits on sailing and on loading at the installation, and the course takes that idea by concept in the simplest stated form: one factor on named time. A plan that needs windows, wave heights or waiting rules states them outside the engine and reflects them in the factor it chooses.'),
  ('marine', 'beginner', 'final', null, 21, 'Skoko et al. print a daily distance of 264 NM for an AHTS. Which stated inputs, at a weather factor of 1, make the engine reproduce that figure?', '["The AHTS Ekene Tide''s stated 12 knots over a dedicated voyage of 120 NM each way, which is a day at sea.", "A speed of 11 knots over a dedicated voyage of 132 NM each way: 264.000000 NM in 24.000000 hours.", "The PSV''s 10 knots over a dedicated voyage of 132 NM each way, the economic speed the table names.", "A speed of 11 knots over 264 NM each way, one day out to the field and one day back again."]'::jsonb, 1, 'The check states 11 knots and 132 NM out and 132 back: 264.000000 NM take 24.000000 hours, one day, the distance Table 4 prints for an AHTS. The Ekene AHTS''s 12 knots is the fixture''s own input, 10 knots is the PSV check, and 264 NM each way would be two days.'),
  ('marine', 'beginner', 'final', null, 22, 'What deck area does the engine load for the Ekene PSV milk run, with 175, 215, 60 and 90 m2 of deck cargo at EKA, EKJ, EKB and EKF?', '["540.000000 m2, the four installations'' deck cargo added up.", "600.000000 m2, the deck area capacity the cargo is checked against.", "215.000000 m2, the jack-up''s cargo, the largest of the four on the route.", "175.000000 m2, the first stop''s cargo, since the deck is unloaded stop by stop."]'::jsonb, 0, 'A milk run carries every installation''s cargo on one deck at once, so the load is 175 + 215 + 60 + 90 = 540.000000 m2 against the 600.000000 m2 capacity. The engine checks the whole voyage''s load, so neither the largest nor the first installation alone is the load.'),
  ('marine', 'beginner', 'final', null, 23, 'Completion brine goes only to the jack-up, which asks for 85 m3 a voyage. Loaded into the PSV''s 400 m3 brine tank, what utilisation does it give?', '["0.240000, the cement tank.", "0.280000, the barite tank.", "0.212500, the emptiest constraint on the voyage.", "0.333333, the mud tank, 200 m3 against its 600 m3."]'::jsonb, 2, '85 over 400 is 0.212500, the lowest of the six tank utilisations and of every constraint on the voyage. The other three figures are the cement, barite and mud tanks, each its own constraint with its own utilisation.'),
  ('marine', 'beginner', 'final', null, 24, 'A vessel is stated with a usable deck fraction of exactly 1. What does that say, and does the engine accept it?', '["That no deck is lost to rails and walkways, which the engine refuses, since a usable fraction must stay below 1.", "That the deck is exactly full, so any deck cargo on the voyage is reported as overloaded on deck area.", "That the fraction is not stated, since 1 is the value the engine reads when no fraction is given.", "That every square metre of the stated deck can take cargo; 1 is the top of the accepted range, so it is accepted."]'::jsonb, 3, 'The usable fraction must be above 0 and at most 1, so 1 is accepted and the deck area capacity is the whole stated deck. The fraction scales a capacity and says nothing about the load, and the engine reads no fraction the call has not stated: a box without one is refused by name.'),
  ('marine', 'beginner', 'final', null, 25, 'Why does the engine require a stated density for every product, with no assumed value?', '["The density sets each tank''s capacity in m3, so without it no tank could be checked at all.", "Treating brine or mud as water would understate the deadweight, so a voyage the vessel cannot carry could pass.", "Fuel burn in port depends on it, since heavy products take longer to pump ashore.", "The density turns deck cargo from square metres into tonnes for the deck load check."]'::jsonb, 1, 'Density turns a bulk volume into a weight in the deadweight. Tanks are stated in m3 and checked by volume, fuel burns are stated per activity, and deck cargo states its weight directly. A product''s weight can be far from water''s, so no single value can stand in for it.'),
  ('marine', 'beginner', 'final', null, 26, 'The first product in the list is stated with a density of 0 t a m3. Which field is refused, and what must it be?', '["The product''s tank, since a product that weighs nothing cannot be held in a tank.", "Nothing is refused: the product simply adds no weight to the voyage''s deadweight load.", "products[0].densityTPerM3, which must be a finite number above 0.", "Nothing is refused: the engine uses the density of water, 1.000000 t a m3, and says so."]'::jsonb, 2, 'The engine''s own words: products[0].densityTPerM3 must be a finite number above 0; got 0. A density turns bulk volume into deadweight, so a weightless product would understate the load; the engine plans with none, substitutes no density of its own, and the tank is not at fault.'),
  ('marine', 'beginner', 'final', null, 27, 'In the products list, the first product''s kind is typed as gas. Which message comes back?', '["A refusal, in the engine''s own words: products[0].kind must be one of \"liquid\", \"dry\"; got \"gas\"", "A plan that treats the gas as a liquid and checks it against its own tank by volume, as for diesel.", "A plan that puts the gas on deck in cylinders and adds their weight to the deck load check.", "A refusal, in the engine''s own words: products[0].kind must be one of \"liquid\", \"dry\", \"deck\"; got \"gas\""]'::jsonb, 0, 'Each product states its kind as liquid or dry, the only two kinds, and any other kind is refused by name, with the value it got in quotation marks. The engine reinterprets no kind and moves no product to the deck.'),
  ('marine', 'beginner', 'final', null, 28, 'Which inputs does the engine''s deadweight load depend on?', '["The deck area and the usable fraction, which set how much cargo the deck can take.", "The tank capacities, since a full tank is taken to be at its stated maximum weight.", "The fuel the voyage burns, since the vessel''s own fuel is counted in its cargo deadweight.", "The deck cargo''s weight, every bulk volume and each product''s stated density."]'::jsonb, 3, 'The deadweight load is the deck weight plus every bulk m3 times its density: 2390.000000 t on the Ekene milk run. It uses loads with no capacity in it, and the cargo deadweight is the planner''s net figure, with no fuel or stores allowance.'),
  ('marine', 'beginner', 'final', null, 29, 'In the reasons of an overloaded voyage, which line comes first?', '["The first overloaded constraint in the stated order, with the binding line printed last.", "The binding constraint''s line, with its load, capacity and percentage; the overloaded lines follow.", "A summary line with the number of overloaded constraints on the voyage, then each constraint by name in the stated order.", "The refusal message for the fullest constraint, since an overload is reported as a refusal."]'::jsonb, 1, 'On the AHTS milk run the reasons begin: the binding constraint is deck area: 540 m2 of 412.5 m2 (130.909091%), and then list overloaded: deck area, deadweight and tank water in turn. The engine prints no count line, and an overloaded voyage is a result.'),
  ('marine', 'beginner', 'final', null, 30, 'The AHTS reason prints 130.909091% where the numeric field reads 1.309091. Why the difference?', '["Inside a sentence the engine prints the utilisation as a percentage to six decimals, trailing zeros dropped; the field is the ratio itself.", "The reason adds a margin for the weather factor, which the numeric field in the table leaves out, so the reason reads higher.", "The reason is rounded to the cent like money in a message, and the field is rounded to six decimals for the table.", "Different constraints: the reason''s figure is the deadweight''s, the field''s is the deck area''s, on the AHTS voyage."]'::jsonb, 0, 'Both describe deck area: 540 m2 of 412.5 m2. The reason writes the ratio as a percentage, a computed figure with a % sign to six decimals, and the numeric field keeps the ratio at full precision, which the course quotes as 1.309091. No weather margin enters either figure.'),
  ('marine', 'beginner', 'final', null, 31, 'On the rainy-season Ekene PSV milk run, the water tank is cut from 1200 to 745 m3 with nothing else changed. What does the engine return?', '["Deck area binding at 0.900000, since the tanks are checked after the deck in the stated order.", "Tank water binding at 1.000000, with the voyage marked as overloaded on the water tank.", "A refusal naming vessel.tanks.water, since the tank is cut to exactly the load it carries.", "Tank water binding at 1.000000 on a feasible voyage: 745 m3 fits a 745 m3 tank."]'::jsonb, 3, '745 m3 of water in a 745 m3 tank is a utilisation of 1.000000, above deck area''s 0.900000, so the water tank binds. By the engine''s stated reading a load exactly at capacity is feasible. The stated order matters only for a tie, and a tank above 0 is a valid capacity however full.'),
  ('marine', 'beginner', 'final', null, 32, 'A planner states the PSV''s brine tank as 0 and also clears the jack-up''s brine, so no stop asks for any. What does the engine return?', '["A refusal on vessel.tanks.brine, since a tank of 0 is refused whether or not it is used.", "A plan with tank brine binding, since an empty zero tank is the fullest possible constraint.", "A feasible plan, with deck area binding at 0.900000, since no stop now asks for brine.", "A refusal naming the jack-up''s cargo, since a drilling unit must always ask for brine."]'::jsonb, 2, 'A zero tank is accepted when nothing is loaded into it, and its utilisation is reported as 0.000000. Only a load of that product is refused. Deck area stays the highest utilisation at 0.900000, and the engine sets no rule about what an installation must ask for.'),
  ('marine', 'beginner', 'final', null, 33, 'A voyage''s binding constraint sits at a utilisation of 0.500000. What does that say about the voyage?', '["Half the voyage is overloaded, so half of its cargo must move to a second voyage.", "Every limit has room left; the binding one is simply where the room would run out first.", "The voyage is short of cargo, which the engine reports among the reasons as grounds to cancel it.", "The binding constraint is legally required to stay at or below half of its stated capacity."]'::jsonb, 1, 'Binding means the highest utilisation, and it does not mean full. At 0.500000 the fullest constraint is half used, so every constraint has room. The engine cancels no voyage for a light load, and binding carries no legal meaning in this course.'),
  ('marine', 'beginner', 'final', null, 34, 'Of these four outcomes on a voyage plan, which one comes back as a refusal?', '["A load of a product whose tank the vessel states as 0, with a stop asking for that product.", "The same cargo on a smaller vessel, overloaded on deck area, deadweight and tank water.", "A deck area and a deck load that share the top utilisation, tied at twelve digits.", "A load of deck cargo exactly equal to the deck area capacity, at a utilisation of 1.000000."]'::jsonb, 0, 'A load of a product with a zero tank is refused, because no voyage of that vessel can carry it. An overloaded voyage is a result with its reasons, a tie is settled by the stated order, and a load exactly at capacity is feasible.'),
  ('marine', 'beginner', 'final', null, 35, 'Which figures of a voyage plan does an overload leave just as they would be if the cargo fitted?', '["The utilisations, which the engine holds at 1.000000 for every overloaded constraint.", "Nothing: the engine recomputes the voyage without the cargo that does not fit.", "The binding constraint, which the engine keeps at the one it named before the cargo was added and the overload appeared.", "The hours, the days and the fuel with its cost, which do not depend on whether the cargo fits."]'::jsonb, 3, 'Time and fuel come from the route, the speeds, the hours and the burns, so the Ekene deck cargo doubled on the PSV still sails 62.072727 hours and burns 19.876364 t. The utilisations show the true ratios, 1.800000 for deck area there, and the engine removes no cargo.'),
  ('marine', 'beginner', 'final', null, 36, 'Of the two Ekene vessels on the rainy-season milk run at 870 a tonne, whose fuel bill is higher, by the engine''s figures?', '["The PSV''s, at 17292.436364 against the AHTS''s 14462.563636.", "The PSV''s, since its voyage is the longer, 62.072727 hours against 60.200000.", "The AHTS''s, at 20775.600000 against the PSV''s 17292.436364.", "Neither: both bills are 17292.436364, since the price and the route are shared."]'::jsonb, 2, 'The AHTS burns 23.880000 t, more an hour in every activity, and 23.880000 t at 870 is 20775.600000; the PSV burns 19.876364 t for 17292.436364. The longer voyage is the PSV''s, yet the AHTS''s higher burns outweigh its shorter hours. 14462.563636 is the PSV''s calm bill.'),
  ('marine', 'beginner', 'final', null, 37, 'On the Ekene PSV milk run, a colleague wants port time named in the rainy-season allowance too. What changes in the engine''s result?', '["Port hours rise to 14.400000 and deck area''s utilisation rises with them, to above 0.900000.", "Port hours rise to 14.400000 and the fuel cost to 17355.076364, while deck area still binds at 0.900000.", "Nothing changes, since the rainy-season allowance is already applied to every activity of the voyage by the plan.", "The fuel cost doubles, since port and field time now both carry the factor of 1.2, just as sailing time does."]'::jsonb, 1, 'Naming port time multiplies the 12 port hours by 1.2, so the voyage takes 64.472727 hours and the fuel cost becomes 17355.076364, 62.640000 more. The cargo and capacities do not move, so deck area still binds at 0.900000. The Ekene plan names sailing and field only.'),
  ('marine', 'beginner', 'final', null, 38, 'A vessel with no cement tank states its cement tank as 0. Which item of the pre-sailing checklist does that satisfy?', '["Feasibility of the voyage, since a tank of 0 can never be overloaded on any voyage it sails.", "The binding constraint is read off, since a tank of 0 is always the binding one on the voyage.", "The fuel and its cost are read with the price they rest on.", "Every product has a stated tank and density, with a tank of 0 where the vessel has none."]'::jsonb, 3, 'The first checklist item asks for a stated tank for every product, 0 where there is none. It says nothing about feasibility: a load of cement into that tank is refused, and a zero tank carrying nothing reports 0.000000, so it never binds a voyage with any other load.'),
  ('marine', 'beginner', 'final', null, 39, 'Which subject does this course hand to the materials course?', '["The stock the cargo replenishes: spares, stock levels and reorder points.", "Vessel hire, port fees and the contract for each vessel taken on charter.", "Discounting a stream of voyage costs back to a single present value.", "Supplier performance and the management of contracts."]'::jsonb, 0, 'The engine takes stated cargo and demand, and stock levels, spares and reorder points belong to the materials course. Vessel hire and contracts are the procurement course''s, discounting is the cash flow course''s, and supplier performance is the contracts course''s.'),
  ('marine', 'beginner', 'final', null, 40, 'The fuel bill is the only cost the engine computes. Where does discounting a stream of such costs to a present value belong?', '["The procurement course, which prices each voyage''s hire against its fuel bill.", "The uncertainty course, which draws the fuel price from a stated distribution.", "The cash flow course: the engine discounts nothing and computes no NPV.", "This course''s Expert tier, which discounts each voyage''s fuel at a stated rate."]'::jsonb, 2, 'Discounting, NPV and cash flows belong to the cash flow course, and the engine discounts nothing at any tier. Procurement owns vessel hire and contracting, and the uncertainty course owns Monte Carlo as a subject.'),
  ('marine', 'beginner', 'final', null, 41, 'A planner needs departure times, and an installation works cargo only in daylight. What does the engine offer?', '["Overnight holding by a daylight rule, at any installation stated as working days only.", "No clock times; the planner states longer field hours for daylight-only cargo work and names that in the plan.", "A departure time for each voyage, set by the engine from the port hours and the voyage''s days.", "A refusal, since an installation that works in daylight only cannot be served on a milk run."]'::jsonb, 1, 'A day in this course is a planning measure of 24 hours with no clock behind it, and the engine sets no departure time and no night holding. Where a plan needs them, it adds them to the stated hours: longer field hours for a daylight-only installation, stated and named in the plan.'),
  ('marine', 'beginner', 'final', null, 42, 'Why does a rainy-season plan for the Ekene PSV milk run keep the same feasibility verdict as the calm plan?', '["The engine plans the capacities once in calm weather and copies the verdict to every season.", "The rainy-season factor lowers the usable deck fraction by just enough to cancel the extra hours.", "The factor of 1.2 is too small to change a verdict, where a larger factor would overload the deck.", "The factor multiplies time and fuel; loads and capacities, and so every utilisation, stay the same in both seasons."]'::jsonb, 3, 'Weather changes the hours, the days and the fuel, and leaves the cargo where it is, so the verdict and the binding deck area at 0.900000 hold in both seasons. No factor, however large, changes a capacity, and the usable fraction is a stated input the weather does not touch.');
